        captions: [[0.0, "Red lines up west of the cone and blue east of it, behind the 35-yard line. The coach and cone are in the middle of the field."], [0.6, "The coach rolls a ball about ten yards up the field."], [1.0, "Two players from each team go out and fight for it."], [3.2, "Red wins the ground ball and the coach calls \"Possession!\", so red is on offense for the whole round."], [3.4, "The next red player pops out right away and gets a free pass."], [5.0, "Free pass! Now it is 3 on 2."], [7.0, "Blue takes the ball away and carries it out to the 35 yard line."], [8.0, "The coach calls \"Release!\" The next player from each team joins: now 4 on 3."], [8.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [13.0, "The ball is at the 35 yard line, so the coach takes it."], [14.0, "The coach says \"Ball in!\" and gives him a free ball."], [15.0, "The offense goes again."], [20.0, "Red has a shot and takes it: goal!"], [22.0, "The coach calls \"Release!\" The next player from each team joins: now 5 on 4."], [22.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [25.0, "The coach says \"New ball!\" and gives him a free ball."], [26.0, "The offense goes again."], [32.0, "Red has a shot and takes it: goal!"], [34.38, "The coach calls \"Reset!\" and everyone goes back to the lines."]],
